using System.Text.Json;
using ExtractorTester.Aggregate;
using ExtractorTester.Config;
using ExtractorTester.Models;
using ExtractorTester.Profiling;

namespace ExtractorTester.Tests;

// Port of tests/test_aggregate.py and tests/test_aggregate_util.py, plus byte parity against
// Fixtures/Aggregate/aggregate_cases.json (generated by gen_aggregate_fixtures.py).
public sealed class AggregateTests
{
    private static readonly JsonDocument Cases = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Fixtures", "Aggregate", "aggregate_cases.json")));

    private static CompareConfig Cfg(long? examples = null, long? snippet = null, double? cutWarn = null)
    {
        var c = new CompareConfig { NameField = "name", MimePrimaryField = "a", MimeSecondaryField = "b" };
        if (examples is { } e) c.ExamplesPerResult = e;
        if (snippet is { } s) c.SnippetChars = s;
        if (cutWarn is { } w) c.CutLinesWarnPct = w;
        c.ApplyPostInit();
        return c;
    }

    private static PairFacts Pair(
        string item, bool changed = false, string kind = "paired", string? pathNew = "r", bool? identical = null,
        long? decOld = null, long? decNew = null, List<ErrorRecord>? errors = null, List<string>? hints = null,
        bool mimeEqual = true, string? mimeOld = null, TextFacts? text = null, string? pathOld = "r") => new()
    {
        ItemId = item,
        Kind = kind,
        PathOld = pathOld,
        PathNew = pathNew,
        Family = "pdf",
        Tier = "root",
        TieBreak = "none",
        MimeEqual = mimeEqual,
        MimeOld = mimeOld,
        FamilyEqual = true,
        FieldDiffs =
        [
            new FieldDiff
            {
                Path = "author", Group = "generic", Status = changed ? "changed" : "same",
                OldValue = "a", NewValue = changed ? "b" : "a",
            },
        ],
        FieldsSame = [],
        Hints = hints ?? [],
        Identical = identical ?? !changed,
        Errors = errors ?? [],
        DecodeErrorsOld = decOld,
        DecodeErrorsNew = decNew,
        Text = text,
    };

    private static ItemResult Item(string item, List<ErrorRecord>? errors = null, string status = "compared",
        List<FieldDiff>? diffs = null) => new()
    {
        ItemId = item, Status = status, MetadataDiffs = diffs ?? [], FilesIdentical = 0, FilesChanged = 0,
        FilesOnlyOld = 0, FilesOnlyNew = 0, Errors = errors ?? [], Seconds = 0.0, StageSeconds = new(),
    };

    private static ErrorRecord Err(ErrorCode code, string severity, string message) =>
        new() { Code = code, Scope = "file", Severity = severity, Message = message };

    private static PairFacts TPair(string item, double sim, long linesCut = 0) => Pair(
        item, pathOld: $"p/{item}", pathNew: $"p/{item}", text: new TextFacts
        {
            RawEqual = false, NormalizedEqual = false, Method = "full", EditSimilarity = sim, Jaccard = sim,
            Relation = "overlapping", OldChars = 1, NewChars = 1, LengthDelta = 0, OldEmpty = false,
            NewEmpty = false, LinesTotal = 10, LinesCut = linesCut, LinesCutPct = 0.0, OversizedRuns = 0,
            Snippets = [], Seconds = 0.0,
        });

    [Fact]
    public void FieldRateOneOfFour()
    {
        var agg = new Aggregator(Cfg());
        for (var i = 0; i < 4; i++) agg.AddPair(Pair($"i{i}", changed: i == 0));
        var fam = agg.Finish().Families[0];
        var m = fam.Fields.Single(f => f.Key == "author:changed");
        Assert.Equal((1L, 4L, 0.25, 1), (m.Count, m.Denominator, m.Rate, m.Examples.Count));
        Assert.Equal(4, fam.Pairs);
        Assert.Equal(3, fam.Identical.Count);
        Assert.Equal("root", fam.Tiers[0].Key);
    }

    [Fact]
    public void ExamplesCappedAndCut()
    {
        var agg = new Aggregator(Cfg(examples: 2, snippet: 20));
        for (var i = 0; i < 5; i++)
            agg.AddPair(Pair($"i{i}", changed: true, mimeEqual: false, mimeOld: new string('x', 50)));
        var fam = agg.Finish().Families[0];
        Assert.Equal(5, fam.MimeChanged.Count);
        Assert.Equal(["i0", "i1"], fam.MimeChanged.Examples.Select(e => e.ItemId));
        Assert.Equal(new string('x', 20), fam.MimeChanged.Examples[0].OldValue);
    }

    [Fact]
    public void ErrorsByCodeAndWarningsSummarised()
    {
        var err = Err(ErrorCode.MISSING_FIELD, "error", "m");
        var warn = Err(ErrorCode.ORPHAN_FILE, "warning", "w");
        var agg = new Aggregator(Cfg());
        agg.AddPair(Pair("i0", errors: [err, err]));
        agg.AddItem(Item("i1", [err, warn]));
        var rep = agg.Finish();
        var e = Assert.Single(rep.Errors);
        Assert.Equal(("MISSING_FIELD", 3L, 3), (e.Key, e.Count, e.Examples.Count));
        Assert.Equal(["ORPHAN_FILE: 1 occurrence(s)"], rep.Warnings);
        Assert.Equal(2, rep.Families[0].FileErrors[0].Count);
    }

    [Fact]
    public void OneSidedPairs()
    {
        var agg = new Aggregator(Cfg());
        agg.AddPair(Pair("i0", kind: "only-in-old", pathNew: null, identical: false));
        var fam = agg.Finish().Families[0];
        Assert.Equal(1, fam.OnlyInOld.Count);
        Assert.Equal(0, fam.Pairs);
    }

    [Fact]
    public void DecodeErrorsSummed()
    {
        var agg = new Aggregator(Cfg());
        agg.AddPair(Pair("i0", decOld: 2, decNew: 1));
        agg.AddPair(Pair("i1"));
        var de = agg.Finish().Families[0].DecodeErrors;
        Assert.Equal((3L, 1), (de.Count, de.Examples.Count));
    }

    [Fact]
    public void ItemMetadataOnlyForComparedAndWarningSkipped()
    {
        var d = new FieldDiff { Path = "t", Group = "item", Status = "changed", OldValue = 1L, NewValue = 2L };
        var agg = new Aggregator(Cfg());
        agg.AddItem(Item("i0", diffs: [d]));
        agg.AddItem(Item("i1", status: "only-in-old", diffs: [d]));
        agg.AddPair(Pair("i0", errors: [Err(ErrorCode.ORPHAN_FILE, "warning", "w")]));
        var rep = agg.Finish();
        Assert.Equal(1, rep.ItemFields[0].Count);
        Assert.Equal(1.0, rep.ItemFields[0].Rate);
        Assert.Empty(rep.Families[0].FileErrors);
    }

    [Fact]
    public void LowestSimilarityExamplesTieOrder()
    {
        var agg = new Aggregator(Cfg(examples: 3));
        foreach (var (item, s) in new[] { ("b", 0.5), ("a", 0.5), ("c", 0.9), ("d", 0.5), ("e", 0.1) })
            agg.AddPair(TPair(item, s));
        var ex = agg.Finish().Families[0].Relations[0].Examples;
        Assert.Equal(["e", "a", "b"], ex.Select(e => e.ItemId));
        Assert.Equal([0.1, 0.5, 0.5], ex.Select(e => e.Similarity!.Value));
        Assert.All(ex, e => Assert.Null(e.OldValue));
    }

    [Fact]
    public void CutLineWarningAndHints()
    {
        var agg = new Aggregator(Cfg(cutWarn: 20));
        agg.AddPair(TPair("a", 0.5, linesCut: 3));
        Assert.True(agg.Finish().Families[0].CutLinesWarning);
        var low = new Aggregator(Cfg(cutWarn: 20));
        low.AddPair(TPair("a", 0.5, linesCut: 1));
        Assert.False(low.Finish().Families[0].CutLinesWarning);
        var h = new Aggregator(Cfg());
        h.AddPair(Pair("a", hints: ["new-more-text"]));
        Assert.Equal("new-more-text", h.Finish().Families[0].Hints[0].Key);
    }

    [Fact]
    public void StatsEmptyAndSingle()
    {
        Assert.Empty(AggStats.Stats([]));
        var s = AggStats.Stats([0.4]);
        Assert.Equal([0.4, 0.4, 0.4], new[] { s["median"], s["p10"], s["min"] }.Select(v => (double)v!));
    }

    [Fact]
    public void LowestKeepsCapLowest()
    {
        var low = new Lowest(2);
        foreach (var (item, sim) in new[] { ("a", 0.9), ("b", 0.2), ("c", 0.5) })
            low.Add(sim, new Example { ItemId = item });
        Assert.Equal(["b", "c"], low.Examples().Select(e => e.ItemId));
    }

    [Fact]
    public void AggregatorIsDeterministic()
    {
        string Run()
        {
            var agg = new Aggregator(Cfg());
            for (var i = 0; i < 4; i++)
            {
                agg.AddPair(Pair($"i{i}", changed: i == 0));
                agg.AddItem(Item($"i{i}"));
            }
            return PyJson.Serialize(agg.Finish());
        }
        Assert.Equal(Run(), Run());
    }

    // ---- fixture parity ------------------------------------------------------------------

    public static IEnumerable<object[]> ScenarioNames() =>
        Cases.RootElement.GetProperty("scenarios").EnumerateObject().Select(p => new object[] { p.Name });

    [Theory]
    [MemberData(nameof(ScenarioNames))]
    public void ReportJsonEqualsPython(string name)
    {
        var sc = Cases.RootElement.GetProperty("scenarios").GetProperty(name);
        var cfgJson = sc.GetProperty("config");
        long? Long(string k) => cfgJson.TryGetProperty(k, out var v) ? v.GetInt64() : null;
        var cfg = Cfg(Long("examples_per_result"), Long("snippet_chars"),
            cfgJson.TryGetProperty("cut_lines_warn_pct", out var w) ? w.GetDouble() : null);
        var agg = new Aggregator(cfg);
        foreach (var p in sc.GetProperty("pairs").EnumerateArray())
            agg.AddPair(PyJson.Deserialize<PairFacts>(p.GetString()!));
        foreach (var i in sc.GetProperty("items").EnumerateArray())
            agg.AddItem(PyJson.Deserialize<ItemResult>(i.GetString()!));
        Assert.Equal(sc.GetProperty("report").GetString(), PyJson.Serialize(agg.Finish()));
    }

    public static IEnumerable<object[]> StatsIndexes() =>
        Enumerable.Range(0, Cases.RootElement.GetProperty("util").GetProperty("stats").GetArrayLength())
            .Select(i => new object[] { i });

    [Theory]
    [MemberData(nameof(StatsIndexes))]
    public void StatsEqualPython(int index)
    {
        var c = Cases.RootElement.GetProperty("util").GetProperty("stats")[index];
        var values = c.GetProperty("values").EnumerateArray().Select(v => v.GetDouble()).ToList();
        Assert.Equal(c.GetProperty("stats").GetString(), PyJson.Serialize(AggStats.Stats(values)));
    }

    public static IEnumerable<object[]> LowestIndexes() =>
        Enumerable.Range(0, Cases.RootElement.GetProperty("util").GetProperty("lowest").GetArrayLength())
            .Select(i => new object[] { i });

    [Theory]
    [MemberData(nameof(LowestIndexes))]
    public void LowestTieOrderEqualsPython(int index)
    {
        var c = Cases.RootElement.GetProperty("util").GetProperty("lowest")[index];
        var low = new Lowest(c.GetProperty("cap").GetInt64());
        var i = 0;
        foreach (var o in c.GetProperty("offers").EnumerateArray())
        {
            string? S(int k) => o[k].ValueKind == JsonValueKind.Null ? null : o[k].GetString();
            low.Add(o[1].GetDouble(), new Example
            {
                ItemId = S(0)!, PathOld = S(2), PathNew = S(3), Note = (i++).ToString(),
            });
        }
        Assert.Equal(
            c.GetProperty("kept_notes").EnumerateArray().Select(n => n.GetString()),
            low.Examples().Select(e => e.Note));
    }

    [Fact]
    public void SlowestTieOrderEqualsPython()
    {
        var c = Cases.RootElement.GetProperty("util").GetProperty("slowest");
        var s = new Slowest(c.GetProperty("n").GetInt32());
        foreach (var o in c.GetProperty("offers").EnumerateArray())
            s.Add(o[0].GetString()!, o[1].GetDouble(), "compared");
        Assert.Equal(c.GetProperty("items").GetString(), PyJson.Serialize(s.Items()));
    }
}
